def draw_marker_pair_lines(grid, marker=1):
    """Draw marker-colored line segments between aligned marker cells, greedily pairing the most distant aligned markers first."""
    rows, cols = len(grid), len(grid[0])
    pts = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == marker]
    pairs = []
    for a in range(len(pts)):
        for b in range(a + 1, len(pts)):
            (r1, c1), (r2, c2) = pts[a], pts[b]
            if r1 == r2 or c1 == c2:
                pairs.append((abs(r1 - r2) + abs(c1 - c2), a, b))
    pairs.sort(reverse=True)
    used, lines = set(), []
    for d, a, b in pairs:
        if a not in used and b not in used:
            used.add(a); used.add(b)
            lines.append((pts[a], pts[b]))
    out = [r[:] for r in grid]
    for (r1, c1), (r2, c2) in lines:
        for r in range(min(r1, r2), max(r1, r2) + 1):
            for c in range(min(c1, c2), max(c1, c2) + 1):
                out[r][c] = marker
    return out


